insert into public.questions
  (id, category, difficulty, question, answers, correct_index, explanation)
values
  ('his-004', 'histoire', 1, 'Qui a été sacré empereur des Français en 1804 ?', array['Louis XVIII', 'Napoléon Ier', 'Charles X', 'Napoléon III'], 1, 'Napoléon Bonaparte s''est couronné lui-même le 2 décembre 1804 à Notre-Dame de Paris.'),
  ('his-005', 'histoire', 1, 'Quelle reine de France a été guillotinée en 1793 ?', array['Marie-Antoinette', 'Catherine de Médicis', 'Anne d''Autriche', 'Marie de Médicis'], 0, 'Marie-Antoinette, épouse de Louis XVI, a été exécutée le 16 octobre 1793, neuf mois après le roi.'),
  ('his-006', 'histoire', 1, 'En quelle année a eu lieu le débarquement allié en Normandie ?', array['1943', '1945', '1942', '1944'], 3, 'Le débarquement a eu lieu le 6 juin 1944, le « Jour J », sur cinq plages normandes.'),
  ('his-007', 'histoire', 2, 'Quel pharaon a été découvert dans un tombeau presque intact en 1922 ?', array['Ramsès II', 'Khéops', 'Toutânkhamon', 'Akhenaton'], 2, 'L''archéologue Howard Carter a découvert la tombe de Toutânkhamon dans la Vallée des Rois, avec son célèbre masque d''or.'),
  ('his-008', 'histoire', 1, 'Quelle bataille de 1815 marque la défaite définitive de Napoléon ?', array['Austerlitz', 'Waterloo', 'Iéna', 'Wagram'], 1, 'À Waterloo, en Belgique actuelle, Napoléon est battu le 18 juin 1815, puis exilé à Sainte-Hélène.'),
  ('his-009', 'histoire', 1, 'Quel roi de France était surnommé le Roi-Soleil ?', array['Louis XIV', 'Louis XIII', 'Louis XV', 'Henri IV'], 0, 'Louis XIV a régné 72 ans (1643-1715), le plus long règne de l''histoire de France. Il a fait de Versailles le siège du pouvoir.'),
  ('his-010', 'histoire', 2, 'En quelle année les Françaises ont-elles voté pour la première fois ?', array['1936', '1919', '1958', '1945'], 3, 'Le droit de vote a été accordé aux femmes en 1944 ; elles ont voté pour la première fois aux municipales d''avril 1945.'),
  ('his-011', 'histoire', 2, 'Tenochtitlan était la capitale de quel empire ?', array['L''Empire inca', 'L''Empire maya', 'L''Empire aztèque', 'L''Empire olmèque'], 2, 'Tenochtitlan, bâtie sur un lac, a été conquise par Hernán Cortés en 1521. Mexico s''élève aujourd''hui à son emplacement.'),
  ('his-012', 'histoire', 3, 'En quelle année Henri IV a-t-il signé l''édit de Nantes ?', array['1685', '1598', '1572', '1610'], 1, 'L''édit de Nantes (1598) accordait aux protestants la liberté de conscience et un droit de culte limité à certains lieux. Louis XIV l''a révoqué en 1685.'),
  ('his-013', 'histoire', 3, 'Quel traité signé en 1957 a créé la Communauté économique européenne ?', array['Le traité de Rome', 'Le traité de Maastricht', 'Le traité de Paris', 'Le traité de Lisbonne'], 0, 'Six pays, dont la France, ont signé le traité de Rome le 25 mars 1957. Le traité de Paris (1951) avait créé la CECA.'),
  ('geo-004', 'geo', 1, 'Quelle est la capitale du Canada ?', array['Toronto', 'Montréal', 'Vancouver', 'Ottawa'], 3, 'Ottawa, en Ontario, est la capitale fédérale, même si Toronto et Montréal sont plus peuplées.'),
  ('geo-005', 'geo', 1, 'Quel est le plus haut sommet des Alpes ?', array['Le Cervin', 'Le mont Rose', 'Le mont Blanc', 'La Barre des Écrins'], 2, 'Le mont Blanc culmine à environ 4 800 m, dans le massif du Mont-Blanc, entre la France et l''Italie.'),
  ('geo-006', 'geo', 1, 'Quel est le plus grand désert chaud du monde ?', array['Le Kalahari', 'Le Sahara', 'Le désert d''Arabie', 'Le désert de Sonora'], 1, 'Le Sahara couvre plus de 9 millions de km². Les déserts froids de l''Antarctique et de l''Arctique sont plus vastes.'),
  ('geo-007', 'geo', 3, 'Avec combien de pays la France métropolitaine a-t-elle une frontière terrestre ?', array['8', '6', '7', '9'], 0, 'Belgique, Luxembourg, Allemagne, Suisse, Italie, Monaco, Andorre et Espagne : 8 voisins terrestres.'),
  ('geo-008', 'geo', 1, 'Dans quel pays se trouve le site du Machu Picchu ?', array['La Bolivie', 'Le Chili', 'L''Équateur', 'Le Pérou'], 3, 'Cette cité inca du XVe siècle est perchée dans les Andes péruviennes, à environ 2 400 m d''altitude.'),
  ('geo-009', 'geo', 1, 'Quel fleuve traverse Le Caire ?', array['Le Tigre', 'L''Euphrate', 'Le Nil', 'Le Congo'], 2, 'Le Nil traverse l''Égypte du sud au nord avant de se jeter dans la Méditerranée par un vaste delta.'),
  ('geo-010', 'geo', 2, 'Quelle est la capitale de la Turquie ?', array['Istanbul', 'Ankara', 'Izmir', 'Antalya'], 1, 'Ankara est la capitale depuis 1923. Istanbul reste la plus grande ville du pays.'),
  ('geo-011', 'geo', 2, 'Quel est le plus petit pays du monde par sa superficie ?', array['Le Vatican', 'Monaco', 'Saint-Marin', 'Le Liechtenstein'], 0, 'Le Vatican, enclavé dans Rome, mesure moins de 0,5 km². Monaco arrive en deuxième position.'),
  ('geo-012', 'geo', 2, 'Quel détroit sépare l''Europe de l''Afrique ?', array['Le détroit du Bosphore', 'Le détroit de Messine', 'Le détroit d''Ormuz', 'Le détroit de Gibraltar'], 3, 'Au plus étroit, le détroit de Gibraltar ne mesure qu''environ 14 km entre l''Espagne et le Maroc.'),
  ('geo-013', 'geo', 3, 'Quel est le lac le plus profond du monde ?', array['Le lac Tanganyika', 'Le lac Supérieur', 'Le lac Baïkal', 'Le lac Victoria'], 2, 'Le Baïkal, en Sibérie, dépasse 1 600 m de profondeur et contient environ un cinquième de l''eau douce liquide de surface.'),
  ('sci-004', 'sciences', 1, 'Quelle est la formule chimique de l''eau ?', array['CO2', 'H2O', 'H2O2', 'HO2'], 1, 'Une molécule d''eau est formée de deux atomes d''hydrogène et d''un atome d''oxygène. H2O2 est l''eau oxygénée.'),
  ('sci-005', 'sciences', 1, 'Quelle planète est surnommée la planète rouge ?', array['Mars', 'Jupiter', 'Vénus', 'Mercure'], 0, 'Sa couleur vient de l''oxyde de fer, autrement dit de la rouille, présent dans ses poussières.'),
  ('sci-006', 'sciences', 1, 'Quel scientifique a formulé la théorie de la relativité ?', array['Isaac Newton', 'Niels Bohr', 'Max Planck', 'Albert Einstein'], 3, 'Einstein a publié la relativité restreinte en 1905 puis la relativité générale en 1915.'),
  ('sci-007', 'sciences', 1, 'Quelle est la planète la plus proche du Soleil ?', array['Vénus', 'Mars', 'Mercure', 'La Terre'], 2, 'Mercure est aussi la plus petite planète du système solaire. Vénus vient en deuxième position.'),
  ('sci-008', 'sciences', 2, 'Combien de chromosomes contient une cellule humaine (hors cellules reproductrices) ?', array['23', '46', '44', '48'], 1, 'Soit 23 paires : une moitié vient de la mère, l''autre du père. Les ovules et spermatozoïdes en ont 23.'),
  ('sci-009', 'sciences', 2, 'Quelle est, environ, la vitesse de la lumière dans le vide ?', array['300 000 km/s', '30 000 km/s', '3 000 000 km/s', '150 000 km/s'], 0, 'La lumière parcourt précisément 299 792 458 m par seconde, soit environ 7,5 fois le tour de la Terre.'),
  ('sci-010', 'sciences', 2, 'Quel est le plus grand organe du corps humain ?', array['Le foie', 'Les poumons', 'Le cerveau', 'La peau'], 3, 'La peau couvre près de 2 m² chez l''adulte. Le foie est le plus gros organe interne.'),
  ('sci-011', 'sciences', 2, 'Qui a découvert la pénicilline en 1928 ?', array['Louis Pasteur', 'Marie Curie', 'Alexander Fleming', 'Robert Koch'], 2, 'Le Britannique Alexander Fleming a remarqué qu''une moisissure empêchait la croissance des bactéries : cette découverte a ouvert l''ère des antibiotiques.'),
  ('sci-012', 'sciences', 3, 'Combien de temps met la lumière du Soleil pour atteindre la Terre ?', array['Environ 8 secondes', 'Environ 8 minutes', 'Environ 1 heure', 'Environ 30 minutes'], 1, 'Elle parcourt environ 150 millions de km en un peu plus de 8 minutes : on voit donc le Soleil tel qu''il était 8 minutes plus tôt.'),
  ('sci-013', 'sciences', 3, 'Quel est l''élément chimique le plus abondant dans la croûte terrestre ?', array['L''oxygène', 'Le silicium', 'Le fer', 'L''aluminium'], 0, 'L''oxygène représente près de la moitié de la masse de la croûte, surtout lié au silicium dans les roches.'),
  ('art-004', 'arts', 1, 'Qui a peint La Nuit étoilée ?', array['Claude Monet', 'Paul Gauguin', 'Paul Cézanne', 'Vincent van Gogh'], 3, 'Van Gogh l''a peinte en 1889 à l''asile de Saint-Rémy-de-Provence, d''après la vue depuis la fenêtre de sa chambre.'),
  ('art-005', 'arts', 1, 'Qui a écrit Le Petit Prince ?', array['Jules Verne', 'Albert Camus', 'Antoine de Saint-Exupéry', 'Jacques Prévert'], 2, 'Publié en 1943, c''est l''un des livres les plus traduits au monde. L''auteur, aviateur, l''a aussi illustré.'),
  ('art-006', 'arts', 1, 'Quel compositeur a écrit Les Quatre Saisons ?', array['Jean-Sébastien Bach', 'Antonio Vivaldi', 'Wolfgang Amadeus Mozart', 'Georg Friedrich Haendel'], 1, 'Ces quatre concertos pour violon du Vénitien Vivaldi ont été publiés en 1725.'),
  ('art-007', 'arts', 1, 'Qui a peint Guernica ?', array['Pablo Picasso', 'Salvador Dalí', 'Joan Miró', 'Francisco de Goya'], 0, 'Picasso l''a peint en 1937 après le bombardement de la ville basque de Guernica pendant la guerre d''Espagne.'),
  ('art-008', 'arts', 2, 'Quel sculpteur a réalisé Le Penseur ?', array['Camille Claudel', 'Michel-Ange', 'Auguste Bartholdi', 'Auguste Rodin'], 3, 'Le Penseur faisait d''abord partie de La Porte de l''Enfer, inspirée de Dante. On peut le voir au musée Rodin à Paris.'),
  ('art-009', 'arts', 2, 'Quel mouvement pictural doit son nom à un tableau de Claude Monet ?', array['Le fauvisme', 'Le cubisme', 'L''impressionnisme', 'Le pointillisme'], 2, 'Le tableau Impression, soleil levant (1872) a inspiré à un critique moqueur le mot « impressionnistes ».'),
  ('art-010', 'arts', 2, 'Dans quelle pièce de Molière trouve-t-on le personnage d''Harpagon ?', array['Le Misanthrope', 'L''Avare', 'Tartuffe', 'Le Malade imaginaire'], 1, 'Harpagon, vieil homme obsédé par sa cassette d''or, est le héros de L''Avare (1668).'),
  ('art-011', 'arts', 2, 'Qui a écrit le recueil de poèmes Les Fleurs du mal ?', array['Charles Baudelaire', 'Arthur Rimbaud', 'Paul Verlaine', 'Stéphane Mallarmé'], 0, 'Publié en 1857, le recueil a valu à Baudelaire un procès pour atteinte aux bonnes mœurs.'),
  ('art-012', 'arts', 3, 'Dans quel musée est exposée La Naissance de Vénus de Botticelli ?', array['Le musée du Louvre', 'Le musée du Prado', 'La National Gallery', 'La galerie des Offices'], 3, 'Le tableau est conservé à la galerie des Offices, à Florence, ville où Botticelli a passé l''essentiel de sa vie.'),
  ('art-013', 'arts', 3, 'Quel architecte a conçu la pyramide du Louvre ?', array['Jean Nouvel', 'Renzo Piano', 'Ieoh Ming Pei', 'Frank Gehry'], 2, 'L''architecte sino-américain I. M. Pei l''a dessinée ; elle a été inaugurée en 1989.'),
  ('spo-004', 'sport', 1, 'Quel tournoi du Grand Chelem de tennis se joue sur terre battue ?', array['Wimbledon', 'Roland-Garros', 'L''US Open', 'L''Open d''Australie'], 1, 'Roland-Garros, à Paris, est le seul des quatre sur terre battue. Wimbledon se joue sur gazon.'),
  ('spo-005', 'sport', 1, 'Combien de joueurs par équipe sont sur le terrain au basket-ball ?', array['5', '6', '7', '4'], 0, 'Chaque équipe aligne 5 joueurs ; les remplacements sont illimités.'),
  ('spo-006', 'sport', 1, 'En quelle année la France a-t-elle remporté sa première Coupe du monde de football ?', array['2018', '1986', '2006', '1998'], 3, 'Les Bleus ont battu le Brésil 3-0 en finale au Stade de France. Ils ont gagné leur deuxième titre en 2018.'),
  ('spo-007', 'sport', 1, 'Dans quel sport utilise-t-on un volant ?', array['Le squash', 'Le tennis de table', 'Le badminton', 'Le padel'], 2, 'Le volant, traditionnellement fait de plumes d''oie, peut dépasser 400 km/h lors d''un smash.'),
  ('spo-008', 'sport', 2, 'Combien de points rapporte un essai au rugby à XV ?', array['3', '5', '4', '6'], 1, 'Un essai vaut 5 points, et la transformation qui suit peut en ajouter 2. L''essai de pénalité, lui, vaut 7 points.'),
  ('spo-009', 'sport', 2, 'Quelle distance parcourt-on lors d''un marathon ?', array['42,195 km', '40 km', '44,5 km', '39,5 km'], 0, 'Cette distance a été fixée officiellement en 1921, sur la base du parcours des JO de Londres 1908.'),
  ('spo-010', 'sport', 2, 'Combien de trous compte un parcours de golf standard ?', array['9', '12', '24', '18'], 3, 'Le standard de 18 trous vient du parcours de St Andrews, en Écosse, au XVIIIe siècle.'),
  ('spo-011', 'sport', 2, 'Combien de sets faut-il gagner pour remporter un match masculin en Grand Chelem ?', array['2', '4', '3', '5'], 2, 'Les matchs masculins se jouent en 3 sets gagnants (5 au maximum), les matchs féminins en 2 sets gagnants.'),
  ('spo-012', 'sport', 3, 'En boxe anglaise professionnelle masculine, combien de temps dure un round ?', array['2 minutes', '3 minutes', '4 minutes', '5 minutes'], 1, 'Chaque round de 3 minutes est suivi d''une minute de repos. Chez les femmes professionnelles, il dure en général 2 minutes.'),
  ('spo-013', 'sport', 3, 'En quelle année ont eu lieu les premiers Jeux olympiques modernes ?', array['1896', '1900', '1888', '1912'], 0, 'Relancés à l''initiative de Pierre de Coubertin, ils se sont tenus à Athènes en 1896.'),
  ('act-004', 'actu', 1, 'Quel pays a remporté l''Euro de football 2024 ?', array['L''Angleterre', 'La France', 'L''Allemagne', 'L''Espagne'], 3, 'L''Espagne a battu l''Angleterre 2-1 en finale à Berlin et remporté son quatrième Euro, un record.'),
  ('act-005', 'actu', 1, 'Quel nageur français a remporté quatre médailles d''or individuelles aux JO de Paris 2024 ?', array['Florent Manaudou', 'Maxime Grousset', 'Léon Marchand', 'Yannick Agnel'], 2, 'Léon Marchand a gagné le 200 m papillon, le 200 m brasse, le 200 m et le 400 m quatre nages.'),
  ('act-006', 'actu', 1, 'Qui a été élu président des États-Unis en novembre 2024 ?', array['Kamala Harris', 'Donald Trump', 'Joe Biden', 'Ron DeSantis'], 1, 'Donald Trump a battu Kamala Harris et entamé en janvier 2025 un second mandat, non consécutif au premier.'),
  ('act-007', 'actu', 1, 'Lors de la cérémonie d''ouverture des JO de Paris 2024, sur quel fleuve les athlètes ont-ils défilé ?', array['La Seine', 'La Loire', 'Le Rhône', 'La Marne'], 0, 'Pour la première fois, la cérémonie s''est déroulée hors d''un stade : les délégations ont défilé en bateau sur la Seine.'),
  ('act-008', 'actu', 2, 'Quel nom a choisi le pape élu en mai 2025 ?', array['Pie XIII', 'Jean-Paul III', 'Benoît XVII', 'Léon XIV'], 3, 'L''Américain Robert Francis Prevost a été élu le 8 mai 2025, après la mort du pape François.'),
  ('act-009', 'actu', 2, 'Quel pays a remporté l''Eurovision 2024 ?', array['La Croatie', 'L''Italie', 'La Suisse', 'La France'], 2, 'Nemo a gagné pour la Suisse avec la chanson « The Code ». La Croatie a fini deuxième.'),
  ('act-010', 'actu', 2, 'Qui a été nommé Premier ministre de la France en septembre 2024 ?', array['François Bayrou', 'Michel Barnier', 'Gabriel Attal', 'Édouard Philippe'], 1, 'Michel Barnier a été nommé le 5 septembre 2024. Son gouvernement a été renversé par une motion de censure en décembre.'),
  ('act-011', 'actu', 2, 'Quel club a remporté sa première Ligue des champions en 2025 ?', array['Le Paris Saint-Germain', 'L''Inter Milan', 'Arsenal', 'Le FC Barcelone'], 0, 'Le PSG a battu l''Inter Milan 5-0 en finale à Munich, le 31 mai 2025, un écart record en finale.'),
  ('act-012', 'actu', 3, 'Quelle ville a accueilli l''Exposition universelle 2025 ?', array['Dubaï', 'Riyad', 'Milan', 'Osaka'], 3, 'L''Expo 2025 s''est tenue à Osaka, au Japon. Dubaï avait accueilli la précédente et Riyad organisera celle de 2030.'),
  ('act-013', 'actu', 3, 'Quel joueur a remporté le Ballon d''or 2024 ?', array['Vinícius Júnior', 'Jude Bellingham', 'Rodri', 'Kylian Mbappé'], 2, 'Le milieu espagnol de Manchester City, champion d''Europe 2024, a devancé Vinícius Júnior.'),
  ('div-004', 'divers', 1, 'Combien de jours compte une année bissextile ?', array['365', '366', '364', '367'], 1, 'Le 29 février est ajouté environ tous les 4 ans pour rattraper le décalage avec la course de la Terre autour du Soleil.'),
  ('div-005', 'divers', 1, 'Combien de cases compte un échiquier ?', array['64', '81', '100', '49'], 0, 'Un échiquier est un carré de 8 cases sur 8, alternant cases claires et foncées.'),
  ('div-006', 'divers', 1, 'Quelle est la monnaie du Japon ?', array['Le won', 'Le yuan', 'Le baht', 'Le yen'], 3, 'Le yen est la monnaie japonaise. Le won est utilisé en Corée, le yuan en Chine et le baht en Thaïlande.'),
  ('div-007', 'divers', 1, 'Combien de cartes compte un jeu classique, sans les jokers ?', array['54', '32', '52', '48'], 2, 'Quatre couleurs de 13 cartes : 52. Avec deux jokers, on arrive à 54 ; le jeu de belote en a 32.'),
  ('div-008', 'divers', 2, 'Combien de minutes compte une journée de 24 heures ?', array['1 240', '1 440', '1 600', '1 340'], 1, '24 heures × 60 minutes = 1 440 minutes, soit 86 400 secondes.'),
  ('div-009', 'divers', 2, 'Dans quelle ville se trouve la célèbre statue du Manneken-Pis ?', array['Bruxelles', 'Amsterdam', 'Anvers', 'Liège'], 0, 'Cette petite statue de bronze d''environ 55 cm est un symbole de Bruxelles ; elle possède plus de 1 000 costumes.'),
  ('div-010', 'divers', 2, 'Quel est l''ingrédient principal du houmous ?', array['La lentille', 'Le haricot blanc', 'La fève', 'Le pois chiche'], 3, 'Le houmous est une purée de pois chiches mélangée à du tahini (crème de sésame), du citron et de l''ail.'),
  ('div-011', 'divers', 2, 'Combien de zéros compte un milliard écrit en chiffres ?', array['6', '12', '9', '10'], 2, 'Un milliard s''écrit 1 000 000 000, soit mille millions. Un million a 6 zéros.'),
  ('div-012', 'divers', 3, 'Comment appelle-t-on un polygone à 12 côtés ?', array['Un décagone', 'Un dodécagone', 'Un ennéagone', 'Un hendécagone'], 1, '« Dodéca » signifie douze en grec. Le décagone a 10 côtés, l''ennéagone 9 et l''hendécagone 11.'),
  ('div-013', 'divers', 3, 'En chiffres romains, que vaut MCM ?', array['1900', '1100', '2100', '1950'], 0, 'M vaut 1 000 et CM vaut 900 (C placé avant M se retranche) : 1 000 + 900 = 1 900.'),
  ('his-014', 'histoire', 1, 'Quel navigateur a atteint l''Amérique en 1492 ?', array['Christophe Colomb', 'Vasco de Gama', 'Fernand de Magellan', 'Amerigo Vespucci'], 0, 'Au service des Rois catholiques d''Espagne, Colomb aborde une île des Bahamas le 12 octobre 1492, persuadé d''avoir atteint les Indes.'),
  ('his-015', 'histoire', 1, 'En quelle année a commencé la Première Guerre mondiale ?', array['1912', '1914', '1916', '1918'], 1, 'Le conflit éclate fin juillet 1914, un mois après l''assassinat de l''archiduc François-Ferdinand à Sarajevo (28 juin), puis s''étend à l''Europe début août. Il prend fin en 1918.'),
  ('his-016', 'histoire', 1, 'Qui a été le premier homme à marcher sur la Lune, en 1969 ?', array['Buzz Aldrin', 'Youri Gagarine', 'Neil Armstrong', 'John Glenn'], 2, 'Le 21 juillet 1969 (heure française), Armstrong pose le pied sur la Lune lors de la mission Apollo 11, suivi de Buzz Aldrin.'),
  ('his-017', 'histoire', 1, 'Quel paquebot a fait naufrage en avril 1912 lors de son voyage inaugural ?', array['Le Lusitania', 'L''Olympic', 'Le Normandie', 'Le Titanic'], 3, 'Le Titanic a heurté un iceberg dans l''Atlantique Nord dans la nuit du 14 au 15 avril 1912 ; environ 1 500 personnes ont péri.'),
  ('his-018', 'histoire', 2, 'Quel chef gaulois a été vaincu par Jules César à Alésia ?', array['Vercingétorix', 'Ambiorix', 'Brennus', 'Dumnorix'], 0, 'Assiégé à Alésia en 52 av. J.-C., Vercingétorix se rend à César. Il est exécuté à Rome quelques années plus tard.'),
  ('his-019', 'histoire', 2, 'Quelle jeune femme a aidé à libérer Orléans, assiégée par les Anglais, en 1429 ?', array['Blanche de Castille', 'Jeanne d''Arc', 'Aliénor d''Aquitaine', 'Anne de Bretagne'], 1, 'Après Orléans, Jeanne d''Arc fait sacrer Charles VII à Reims. Capturée, elle est brûlée à Rouen en 1431.'),
  ('his-020', 'histoire', 2, 'En quelle année l''esclavage a-t-il été définitivement aboli dans les colonies françaises ?', array['1794', '1815', '1848', '1870'], 2, 'Le décret du 27 avril 1848, porté par Victor Schœlcher, abolit l''esclavage. Une première abolition de 1794 avait été annulée par Bonaparte en 1802.'),
  ('his-021', 'histoire', 2, 'Comment appelle-t-on le conflit qui a opposé la France et l''Angleterre de 1337 à 1453 ?', array['La guerre de Trente Ans', 'La guerre de Sept Ans', 'Les guerres de Religion', 'La guerre de Cent Ans'], 3, 'Malgré son nom, elle a duré 116 ans, entrecoupée de longues trêves.'),
  ('his-022', 'histoire', 3, 'En quelle année Constantinople a-t-elle été prise par les Ottomans ?', array['1453', '1204', '1492', '1515'], 0, 'Le sultan Mehmed II s''empare de la ville le 29 mai 1453, ce qui met fin à l''Empire byzantin. Elle deviendra Istanbul.'),
  ('his-023', 'histoire', 3, 'Quels traités ont mis fin à la guerre de Trente Ans en 1648 ?', array['Les traités d''Utrecht', 'Les traités de Westphalie', 'Le traité des Pyrénées', 'Le traité de Versailles'], 1, 'Signés à Münster et Osnabrück, ils redessinent l''Europe et donnent notamment à la France une grande partie de l''Alsace.'),
  ('geo-014', 'geo', 1, 'Dans quelle ville se trouve la statue de la Liberté ?', array['Washington', 'New York', 'Boston', 'Philadelphie'], 1, 'Offerte par la France aux États-Unis, elle a été inaugurée en 1886. Sa structure interne a été conçue par Gustave Eiffel.'),
  ('geo-015', 'geo', 1, 'Quelle chaîne de montagnes sépare la France de l''Espagne ?', array['Les Alpes', 'Le Jura', 'Les Pyrénées', 'Les Vosges'], 2, 'Les Pyrénées s''étendent sur environ 430 km, de l''Atlantique à la Méditerranée. Andorre est nichée en leur cœur.'),
  ('geo-016', 'geo', 1, 'Quel est le plus grand pays du monde par sa superficie ?', array['Le Canada', 'La Chine', 'Les États-Unis', 'La Russie'], 3, 'Avec environ 17 millions de km², la Russie est presque deux fois plus vaste que le Canada, deuxième du classement.'),
  ('geo-017', 'geo', 1, 'Quelle est la capitale du Portugal ?', array['Lisbonne', 'Porto', 'Coimbra', 'Faro'], 0, 'Lisbonne est bâtie sur l''estuaire du Tage. Elle a été en grande partie détruite par un séisme en 1755.'),
  ('geo-018', 'geo', 2, 'Quelle est la capitale du Brésil ?', array['Rio de Janeiro', 'Brasília', 'São Paulo', 'Salvador'], 1, 'Brasília a été construite de toutes pièces et inaugurée en 1960 pour remplacer Rio de Janeiro comme capitale.'),
  ('geo-019', 'geo', 2, 'Quelle est la capitale du Maroc ?', array['Casablanca', 'Marrakech', 'Rabat', 'Fès'], 2, 'Rabat est la capitale politique du Maroc, alors que Casablanca en est la plus grande ville et le poumon économique.'),
  ('geo-020', 'geo', 2, 'Dans quel pays se trouve la ville historique de Tombouctou ?', array['Le Niger', 'La Mauritanie', 'Le Burkina Faso', 'Le Mali'], 3, 'Surnommée « la ville aux 333 saints », Tombouctou est célèbre pour ses mosquées en terre et ses manuscrits anciens.'),
  ('geo-021', 'geo', 2, 'Quelle est la capitale de la Nouvelle-Zélande ?', array['Wellington', 'Auckland', 'Christchurch', 'Dunedin'], 0, 'Wellington, au sud de l''île du Nord, est la capitale depuis 1865. Auckland est pourtant la ville la plus peuplée.'),
  ('geo-022', 'geo', 3, 'Quel pays possède le plus de fuseaux horaires, en comptant ses territoires d''outre-mer ?', array['La Russie', 'La France', 'Les États-Unis', 'Le Royaume-Uni'], 1, 'Grâce à ses territoires répartis sur tous les océans, la France couvre 12 fuseaux horaires (13 avec la terre Adélie), contre 11 pour la Russie et les États-Unis.'),
  ('geo-023', 'geo', 3, 'Quel est le plus long fleuve d''Europe ?', array['Le Danube', 'Le Rhin', 'La Volga', 'Le Dniepr'], 2, 'La Volga coule entièrement en Russie sur environ 3 500 km avant de se jeter dans la mer Caspienne. Le Danube arrive deuxième.'),
  ('sci-014', 'sciences', 1, 'Combien de pattes possède une araignée ?', array['6', '10', '8', '12'], 2, 'Les araignées sont des arachnides et ont 8 pattes, contrairement aux insectes, qui en ont 6.'),
  ('sci-015', 'sciences', 1, 'Quelle est l''étoile la plus proche de la Terre ?', array['Proxima du Centaure', 'Sirius', 'L''étoile Polaire', 'Le Soleil'], 3, 'Le Soleil est une étoile, à environ 150 millions de km. Après lui, la plus proche est Proxima du Centaure, à un peu plus de 4 années-lumière.'),
  ('sci-016', 'sciences', 1, 'À quelle température l''eau pure bout-elle au niveau de la mer ?', array['100 °C', '90 °C', '80 °C', '120 °C'], 0, 'À la pression atmosphérique normale, l''eau bout à 100 °C. En altitude, la pression baisse et l''eau bout à plus basse température.'),
  ('sci-017', 'sciences', 1, 'Quel est le plus grand animal vivant sur Terre ?', array['L''éléphant d''Afrique', 'La baleine bleue', 'Le requin-baleine', 'Le cachalot'], 1, 'La baleine bleue peut dépasser 25 m de long et 100 tonnes, ce qui en fait le plus grand animal connu, dinosaures compris.'),
  ('sci-018', 'sciences', 2, 'Quel est le symbole chimique du fer ?', array['Fr', 'F', 'Fe', 'Ir'], 2, 'Fe vient du latin ferrum. F désigne le fluor, Fr le francium et Ir l''iridium.'),
  ('sci-019', 'sciences', 2, 'Combien de cœurs possède une pieuvre ?', array['1', '2', '4', '3'], 3, 'Deux cœurs envoient le sang vers les branchies et un troisième l''envoie dans le reste du corps. Son sang est bleu.'),
  ('sci-020', 'sciences', 2, 'Quel chimiste russe a publié en 1869 un tableau périodique prédisant des éléments encore inconnus ?', array['Dmitri Mendeleïev', 'Antoine Lavoisier', 'Marie Curie', 'John Dalton'], 0, 'Le chimiste russe a classé les éléments selon leur masse et laissé des cases vides pour des éléments encore inconnus, découverts ensuite.'),
  ('sci-021', 'sciences', 2, 'Quel est l''os le plus long du corps humain ?', array['Le tibia', 'Le fémur', 'L''humérus', 'Le péroné'], 1, 'Le fémur, l''os de la cuisse, mesure environ un quart de la taille d''une personne. C''est aussi l''un des plus solides.'),
  ('sci-022', 'sciences', 3, 'Quel physicien a mis en évidence le noyau de l''atome en 1911 ?', array['Niels Bohr', 'Joseph John Thomson', 'Ernest Rutherford', 'James Chadwick'], 2, 'En bombardant une fine feuille d''or, Rutherford a montré que la masse de l''atome est concentrée dans un minuscule noyau.'),
  ('sci-023', 'sciences', 3, 'Quel métal est le meilleur conducteur d''électricité ?', array['Le cuivre', 'L''or', 'L''aluminium', 'L''argent'], 3, 'L''argent conduit un peu mieux que le cuivre, mais il est bien plus cher : c''est pourquoi les câbles électriques sont en cuivre.'),
  ('art-014', 'arts', 1, 'Qui a écrit Roméo et Juliette ?', array['Molière', 'Miguel de Cervantès', 'Johann Wolfgang von Goethe', 'William Shakespeare'], 3, 'Shakespeare a écrit cette tragédie vers 1595. L''histoire des deux amants se déroule à Vérone, en Italie.'),
  ('art-015', 'arts', 1, 'Qui a peint le plafond de la chapelle Sixtine ?', array['Michel-Ange', 'Raphaël', 'Léonard de Vinci', 'Le Caravage'], 0, 'Michel-Ange l''a peint de 1508 à 1512, à la demande du pape Jules II. La Création d''Adam en est la scène la plus célèbre.'),
  ('art-016', 'arts', 1, 'Qui a écrit Les Trois Mousquetaires ?', array['Victor Hugo', 'Alexandre Dumas', 'Jules Verne', 'Honoré de Balzac'], 1, 'Publié en 1844, le roman suit d''Artagnan et ses amis Athos, Porthos et Aramis.'),
  ('art-017', 'arts', 1, 'Quel auteur belge a créé Tintin ?', array['Franquin', 'Peyo', 'Hergé', 'Morris'], 2, 'Tintin apparaît en 1929. Hergé est le pseudonyme de Georges Remi, formé à partir de ses initiales inversées (R. G.).'),
  ('art-018', 'arts', 2, 'Quel compositeur a écrit l''opéra La Flûte enchantée ?', array['Ludwig van Beethoven', 'Richard Wagner', 'Giuseppe Verdi', 'Wolfgang Amadeus Mozart'], 3, 'Mozart l''a créé à Vienne en 1791, quelques semaines avant sa mort, à 35 ans.'),
  ('art-019', 'arts', 2, 'Quel peintre a réalisé Le Déjeuner sur l''herbe en 1863 ?', array['Édouard Manet', 'Claude Monet', 'Auguste Renoir', 'Gustave Courbet'], 0, 'Refusé au Salon officiel, le tableau a fait scandale au Salon des refusés de 1863. Il est exposé au musée d''Orsay.'),
  ('art-020', 'arts', 2, 'Quelle romancière a créé le détective Hercule Poirot ?', array['Mary Shelley', 'Agatha Christie', 'Jane Austen', 'Virginia Woolf'], 1, 'Le détective belge apparaît en 1920 dans La Mystérieuse Affaire de Styles. Agatha Christie est l''une des autrices les plus vendues au monde.'),
  ('art-021', 'arts', 2, 'Qui a écrit le roman Le Rouge et le Noir ?', array['Gustave Flaubert', 'Émile Zola', 'Stendhal', 'Honoré de Balzac'], 2, 'Publié en 1830, le roman raconte l''ascension de Julien Sorel. Stendhal est le pseudonyme d''Henri Beyle.'),
  ('art-022', 'arts', 3, 'Quel peintre a réalisé La Jeune Fille à la perle ?', array['Rembrandt', 'Frans Hals', 'Pieter Bruegel l''Ancien', 'Johannes Vermeer'], 3, 'Ce tableau du peintre néerlandais, peint vers 1665, est conservé au Mauritshuis, à La Haye.'),
  ('art-023', 'arts', 3, 'Quel était le vrai nom de Molière ?', array['Jean-Baptiste Poquelin', 'Jean-Baptiste Lully', 'François-Marie Arouet', 'Pierre Carlet'], 0, 'Fils d''un tapissier du roi, il prend le nom de Molière vers 1644. François-Marie Arouet est le vrai nom de Voltaire.'),
  ('spo-014', 'sport', 1, 'Dans quel pays le judo a-t-il été créé ?', array['Le Japon', 'La Chine', 'La Corée du Sud', 'La Thaïlande'], 0, 'Le judo a été fondé en 1882 à Tokyo par Jigoro Kano. Il est devenu un sport olympique en 1964.'),
  ('spo-015', 'sport', 1, 'Combien de temps dure un match de football, hors arrêts de jeu et prolongations ?', array['80 minutes', '90 minutes', '100 minutes', '120 minutes'], 1, 'Un match se joue en deux mi-temps de 45 minutes. L''arbitre ajoute ensuite du temps additionnel pour compenser les arrêts.'),
  ('spo-016', 'sport', 1, 'Combien d''anneaux figurent sur le drapeau olympique ?', array['4', '6', '5', '7'], 2, 'Les cinq anneaux entrelacés, dessinés par Pierre de Coubertin, symbolisent l''union des continents.'),
  ('spo-017', 'sport', 1, 'Dans quel sport réalise-t-on un « strike » en renversant toutes les quilles d''un coup ?', array['Le billard', 'Le curling', 'La pétanque', 'Le bowling'], 3, 'Un strike, c''est renverser les 10 quilles dès le premier lancer. Une partie parfaite, 12 strikes d''affilée, vaut 300 points.'),
  ('spo-018', 'sport', 2, 'À quelle hauteur se trouve un panier de basket-ball ?', array['3,05 m', '2,80 m', '3,25 m', '3,50 m'], 0, 'Le cercle est fixé à 10 pieds, soit 3,05 m. Cette hauteur n''a pas changé depuis l''invention du jeu en 1891.'),
  ('spo-019', 'sport', 2, 'Combien de joueurs par équipe sont sur le terrain au volley-ball ?', array['5', '6', '7', '8'], 1, 'Chaque équipe aligne 6 joueurs, qui tournent d''une position chaque fois qu''ils récupèrent le service.'),
  ('spo-020', 'sport', 2, 'Sur quelle surface se joue le tournoi de Wimbledon ?', array['La terre battue', 'Le dur', 'Le gazon', 'La moquette'], 2, 'Créé en 1877 à Londres, Wimbledon est le plus ancien tournoi de tennis du monde et le seul Grand Chelem sur gazon.'),
  ('spo-021', 'sport', 2, 'Au tennis, comment appelle-t-on le score de 40-40 ?', array['Avantage', 'Jeu blanc', 'Tie-break', 'Égalité'], 3, 'À 40-40, il faut ensuite marquer deux points d''affilée : le premier donne l''avantage, le second le jeu.'),
  ('spo-022', 'sport', 3, 'Quel pays a remporté la première Coupe du monde de football, en 1930 ?', array['L''Uruguay', 'L''Argentine', 'Le Brésil', 'L''Italie'], 0, 'Organisateur du tournoi, l''Uruguay a battu l''Argentine 4-2 en finale à Montevideo.'),
  ('spo-023', 'sport', 3, 'Au hockey sur glace, combien de joueurs par équipe sont sur la glace, gardien compris ?', array['5', '6', '7', '8'], 1, 'Chaque équipe aligne un gardien et 5 joueurs de champ, qui se relaient très souvent en cours de jeu.'),
  ('act-014', 'actu', 1, 'Quel pays a remporté la Coupe du monde de football 2022 au Qatar ?', array['La France', 'L''Argentine', 'La Croatie', 'Le Brésil'], 1, 'L''Argentine de Lionel Messi a battu la France aux tirs au but (3-3, puis 4-2) en finale, le 18 décembre 2022.'),
  ('act-015', 'actu', 1, 'Quelle équipe a remporté la Coupe du monde de rugby 2023, organisée en France ?', array['La Nouvelle-Zélande', 'La France', 'L''Afrique du Sud', 'L''Irlande'], 2, 'Les Springboks ont battu la Nouvelle-Zélande 12-11 en finale au Stade de France, remportant un 4e titre record.'),
  ('act-016', 'actu', 1, 'Quel pape est mort le 21 avril 2025 ?', array['Benoît XVI', 'Jean-Paul II', 'Paul VI', 'François'], 3, 'Le pape François, premier pape sud-américain, est mort à 88 ans, après douze ans de pontificat.'),
  ('act-017', 'actu', 1, 'Quel roi a été couronné à Londres en mai 2023 ?', array['Charles III', 'William V', 'George VII', 'Édouard IX'], 0, 'Charles III, roi depuis la mort d''Élisabeth II en septembre 2022, a été couronné à l''abbaye de Westminster le 6 mai 2023.'),
  ('act-018', 'actu', 2, 'Quel coureur a remporté le Tour de France 2025 ?', array['Jonas Vingegaard', 'Tadej Pogačar', 'Remco Evenepoel', 'Primož Roglič'], 1, 'Le Slovène a décroché son quatrième Tour de France, devant le Danois Jonas Vingegaard.'),
  ('act-019', 'actu', 2, 'Quel joueur a remporté le tournoi masculin de Roland-Garros 2025 ?', array['Jannik Sinner', 'Novak Djokovic', 'Carlos Alcaraz', 'Alexander Zverev'], 2, 'L''Espagnol a battu Jannik Sinner en cinq sets lors d''une finale de plus de cinq heures, après avoir sauvé trois balles de match.'),
  ('act-020', 'actu', 2, 'En 2024, quel pays est devenu le premier à inscrire explicitement la liberté de recourir à l''IVG dans sa Constitution ?', array['L''Espagne', 'La Suède', 'L''Irlande', 'La France'], 3, 'Le Parlement réuni en Congrès à Versailles a adopté cette révision constitutionnelle le 4 mars 2024.'),
  ('act-021', 'actu', 2, 'Selon l''ONU, quel pays est devenu en 2023 le plus peuplé du monde ?', array['L''Inde', 'La Chine', 'L''Indonésie', 'Les États-Unis'], 0, 'L''Inde a dépassé la Chine en 2023 avec plus de 1,4 milliard d''habitants, selon les estimations des Nations unies.'),
  ('act-022', 'actu', 3, 'Quel pays est devenu en mars 2024 le 32e membre de l''OTAN ?', array['La Finlande', 'La Suède', 'L''Ukraine', 'L''Autriche'], 1, 'La Suède a rejoint l''Alliance le 7 mars 2024, un an après la Finlande, rompant avec deux siècles de neutralité.'),
  ('act-023', 'actu', 3, 'Quelle mission a réalisé en septembre 2024 la première sortie dans l''espace d''astronautes privés ?', array['Inspiration4', 'Axiom Mission 3', 'Polaris Dawn', 'Artemis I'], 2, 'Le 12 septembre 2024, le milliardaire Jared Isaacman et l''ingénieure Sarah Gillis se sont hissés hors de leur capsule Crew Dragon de SpaceX.'),
  ('div-014', 'divers', 1, 'Combien de couleurs compte traditionnellement un arc-en-ciel ?', array['5', '6', '7', '8'], 2, 'Rouge, orange, jaune, vert, bleu, indigo et violet : Isaac Newton a retenu ce découpage en sept couleurs.'),
  ('div-015', 'divers', 1, 'Quel animal est un emblème traditionnel de la France ?', array['Le loup', 'Le lion', 'L''ours', 'Le coq'], 3, 'Le coq viendrait d''un jeu de mots latin : gallus signifie à la fois « coq » et « Gaulois ».'),
  ('div-016', 'divers', 1, 'Quel fruit est l''ingrédient principal du guacamole ?', array['L''avocat', 'La mangue', 'La papaye', 'La goyave'], 0, 'Né au Mexique, le guacamole tire son nom du nahuatl, la langue des Aztèques (āhuacamōlli, « sauce d''avocat »).'),
  ('div-017', 'divers', 1, 'Combien de mois de l''année comptent 31 jours ?', array['5', '7', '6', '8'], 1, 'Janvier, mars, mai, juillet, août, octobre et décembre ont 31 jours. Astuce : comptez sur les bosses de vos poings.'),
  ('div-018', 'divers', 2, 'Sur un dé à six faces classique, quelle est la somme de deux faces opposées ?', array['6', '8', '7', '9'], 2, 'Le 1 est opposé au 6, le 2 au 5 et le 3 au 4 : chaque paire fait 7.'),
  ('div-019', 'divers', 2, 'Malgré son nom, de quelle couleur est la « boîte noire » d''un avion ?', array['Noire', 'Rouge', 'Verte', 'Orange'], 3, 'Elle est le plus souvent peinte en orange vif (le jaune vif est aussi autorisé) pour être retrouvée facilement après un accident.'),
  ('div-020', 'divers', 2, 'Quelles noces célèbre-t-on pour 50 ans de mariage ?', array['Les noces d''or', 'Les noces d''argent', 'Les noces de diamant', 'Les noces de platine'], 0, 'On fête les noces d''argent à 25 ans, d''or à 50 ans et de diamant à 60 ans de mariage.'),
  ('div-021', 'divers', 2, 'Aux dames internationales (damier de 100 cases), combien de pions chaque joueur a-t-il au départ ?', array['12', '20', '16', '24'], 1, 'Chaque joueur place 20 pions sur les cases foncées des quatre premières rangées. Les dames anglaises, sur 64 cases, en utilisent 12.'),
  ('div-022', 'divers', 3, 'Comment s''appelle le symbole « & » ?', array['L''arobase', 'L''astérisque', 'L''esperluette', 'Le tilde'], 2, 'L''esperluette vient de la ligature des lettres e et t, qui forment le mot latin et.'),
  ('div-023', 'divers', 3, 'Combien de lettres compte l''alphabet grec ?', array['22', '26', '28', '24'], 3, 'Il va d''alpha à oméga. L''alphabet hébreu en compte 22, l''alphabet latin 26 et l''alphabet arabe 28.')
