-- Fichier généré par tool/generate_seed.dart depuis supabase/questions/questions.json.
-- Ne pas modifier à la main : relancer `dart run tool/generate_seed.dart`.
-- Appliqué par `supabase db reset` (local) ou `supabase db push --include-seed`.

on conflict (id) do update
set category = excluded.category,
    difficulty = excluded.difficulty,
    question = excluded.question,
    answers = excluded.answers,
    correct_index = excluded.correct_index,
    explanation = excluded.explanation,
    active = true,
    updated_at = now()
where (questions.category, questions.difficulty, questions.question,
       questions.answers, questions.correct_index, questions.explanation,
       questions.active)
  is distinct from
      (excluded.category, excluded.difficulty, excluded.question,
       excluded.answers, excluded.correct_index, excluded.explanation,
       true);

-- Questions absentes du fichier (lot hors ligne de l'app, questions
-- retirées) : désactivées, jamais supprimées (référencées par les sessions).
update public.questions
   set active = false, updated_at = now()
 where active
   and id <> all (array['his-004', 'his-005', 'his-006', 'his-007', 'his-008', 'his-009', 'his-010', 'his-011', 'his-012', 'his-013', 'geo-004', 'geo-005', 'geo-006', 'geo-007', 'geo-008', 'geo-009', 'geo-010', 'geo-011', 'geo-012', 'geo-013', 'sci-004', 'sci-005', 'sci-006', 'sci-007', 'sci-008', 'sci-009', 'sci-010', 'sci-011', 'sci-012', 'sci-013', 'art-004', 'art-005', 'art-006', 'art-007', 'art-008', 'art-009', 'art-010', 'art-011', 'art-012', 'art-013', 'spo-004', 'spo-005', 'spo-006', 'spo-007', 'spo-008', 'spo-009', 'spo-010', 'spo-011', 'spo-012', 'spo-013', 'act-004', 'act-005', 'act-006', 'act-007', 'act-008', 'act-009', 'act-010', 'act-011', 'act-012', 'act-013', 'div-004', 'div-005', 'div-006', 'div-007', 'div-008', 'div-009', 'div-010', 'div-011', 'div-012', 'div-013', 'his-014', 'his-015', 'his-016', 'his-017', 'his-018', 'his-019', 'his-020', 'his-021', 'his-022', 'his-023', 'geo-014', 'geo-015', 'geo-016', 'geo-017', 'geo-018', 'geo-019', 'geo-020', 'geo-021', 'geo-022', 'geo-023', 'sci-014', 'sci-015', 'sci-016', 'sci-017', 'sci-018', 'sci-019', 'sci-020', 'sci-021', 'sci-022', 'sci-023', 'art-014', 'art-015', 'art-016', 'art-017', 'art-018', 'art-019', 'art-020', 'art-021', 'art-022', 'art-023', 'spo-014', 'spo-015', 'spo-016', 'spo-017', 'spo-018', 'spo-019', 'spo-020', 'spo-021', 'spo-022', 'spo-023', 'act-014', 'act-015', 'act-016', 'act-017', 'act-018', 'act-019', 'act-020', 'act-021', 'act-022', 'act-023', 'div-014', 'div-015', 'div-016', 'div-017', 'div-018', 'div-019', 'div-020', 'div-021', 'div-022', 'div-023']);
